channels('phone-request',async payload=>{
  if(session||authenticationPending)throw Error('Sign-in already open');
  const phone=payload?.phone;
  if(typeof phone!=='string'||!/^\+[1-9]\d{6,14}$/.test(phone))throw Error('Invalid phone number');
  limitRequests();limitKey(phoneCooldowns,phone,now());
  if(phoneCooldowns.has(phone))throw Error('Too many attempts');
  phoneCooldowns.set(phone,{expires:now()+60000});
  const flow={phone,sent:now(),tries:0,ready:false,generation:authGeneration};phoneFlow=flow;
  try{await provider.sendPhoneCode(phone);if(phoneFlow!==flow||flow.generation!==authGeneration)throw Error('Authentication superseded');flow.ready=true;return true}
  catch(err){if(phoneFlow===flow)phoneFlow=null;throw err}
});
channels('phone-verify',payload=>authenticate(async()=>{
  const flow=phoneFlow;
  if(session||!flow?.ready||flow.generation!==authGeneration||flow.tries>=5||now()-flow.sent>=600000||payload?.phone!==flow.phone||typeof payload?.code!=='string'||!/^\d{6}$/.test(payload.code))throw Error('Invalid or expired code');
  limitRequests();flow.tries++;
  const user=await provider.verifyPhoneCode(flow.phone,payload.code);
  if(phoneFlow!==flow||flow.generation!==authGeneration||now()-flow.sent>=600000)throw Error('Invalid or expired code');
  phoneFlow=null;return user;
}));
channels('phone-cancel',()=>{phoneFlow=null;return true});

